window.BLOCK_CONFIG={"assignmentKey": "gov-cs1-4-review-2026-v2", "title": "CS 1–4 Civic Engagement Review", "description": "Content Statements 1–4 • 40 scenario-based Review questions", "practice": "Evaluate civic action plans, defend organizations and media choices, assess source evidence and explain how democratic agreement develops.", "mode": "review", "contentRevision": "20261112-full-review-audit"};
window.BLOCK_QUESTIONS=[{"id": "q1", "cs": "CS 1", "contentStatement": 1, "topic": "CS 1 • Civic action and policy choices", "readingTitle": "Classroom scenario", "reading": "Residents identify repeated near misses at a crossing. Some favor a signal; others favor a raised crossing. They have not collected crash records, checked road ownership or estimated either option’s cost.", "prompt": "Which next step best turns the concern into a defensible civic proposal?", "choices": ["Seek funding for the preferred signal, then collect evidence about alternative crossing designs", "Choose the remedy with the most supporters, then ask officials which agency owns the road", "Start a candidate campaign, treating victory as approval for the preferred crossing project", "Gather local evidence, compare feasible remedies and contact the responsible road authority"], "answer": 3, "source": "reference.html#plan", "where": "Read “CS 1 • Build an action plan.” Separate problem research and authority from commitment to a particular remedy.", "hint": "Separate problem research and authority from commitment to a particular remedy.", "explanation": "A workable proposal needs relevant evidence, feasible alternatives and the institution able to act. Choosing a remedy or winning a campaign does not complete those steps.", "skill": "plan"}, {"id": "q2", "cs": "CS 1", "contentStatement": 1, "topic": "CS 1 • Civic action and policy choices", "readingTitle": "Classroom scenario", "reading": "Students want to change a requirement written into a state licensing statute. The change requires an amendment to that statute, rather than a change to a city rule or a school policy.", "prompt": "Which approach most directly pursues the requested change through the appropriate institution?", "choices": ["Ask city council to amend its local licensing ordinance so it replaces the state requirement", "Present the group’s evidence and proposed statutory language to members of the state legislature", "Ask the licensing agency to treat a public comment as an enacted amendment to the statute", "Ask the school board to adopt the amendment as part of the district’s graduation policy"], "answer": 1, "source": "reference.html#authority", "where": "Read “CS 1 • Choose the responsible institution.” Distinguish the body that can amend the statute from bodies that administer other rules.", "hint": "Distinguish the body that can amend the statute from bodies that administer other rules.", "explanation": "The scenario specifies a state statutory amendment. State legislators consider changes to state law; other institutions cannot substitute their own procedures for that legislative action.", "skill": "authority"}, {"id": "q3", "cs": "CS 1", "contentStatement": 1, "topic": "CS 1 • Civic action and policy choices", "readingTitle": "Classroom scenario", "reading": "Volunteers help a mayoral candidate win an election. After the election, transit employees study ridership and revise service schedules under the city’s existing policy procedures.", "prompt": "Which conclusion correctly distinguishes the two processes shown?", "choices": ["Both activities are election procedures because the service changes occur after a campaign", "The campaign implements a public program; the scheduling work determines who holds office", "The campaign concerns gaining office; the scheduling work concerns carrying out public policy", "Both activities are administrative duties because each may influence residents’ daily lives"], "answer": 2, "source": "reference.html#process", "where": "Read “CS 1 • Political and public policy processes.” Consider whether each action selects officeholders or carries out an institutional function.", "hint": "Consider whether each action selects officeholders or carries out an institutional function.", "explanation": "The campaign is a clear political process for acquiring power. Transit scheduling is an institutional public policy function. Political influence and policy work can overlap without becoming identical.", "skill": "process"}, {"id": "q4", "cs": "CS 1", "contentStatement": 1, "topic": "CS 1 • Civic action and policy choices", "readingTitle": "Classroom scenario", "reading": "A city can spend up to $30,000 on access to a public facility. A ramp costs $24,000 and would need a permit. A lift costs $42,000. Volunteers can collect access information, but approved contractors must perform construction.", "prompt": "Which action plan is feasible under the stated constraints?", "choices": ["Assign volunteers to build the ramp first, then request a permit after the city reviews access", "Assign volunteers to document needs, seek ramp approval and schedule authorized construction", "Commit the city to the lift, then assume a future donation will cover the remaining cost", "Spend the grant on publicity for both designs, leaving approval and construction unassigned"], "answer": 1, "source": "reference.html#plan", "where": "Read “CS 1 • Build an action plan.” A plan must satisfy the budget, assign tasks and follow the stated implementation conditions.", "hint": "A plan must satisfy the budget, assign tasks and follow the stated implementation conditions.", "explanation": "The ramp fits the budget, and the proposed sequence assigns appropriate work while obtaining permission. The other plans ignore a constraint or leave the physical goal unimplemented.", "skill": "plan"}, {"id": "q5", "cs": "CS 1", "contentStatement": 1, "topic": "CS 1 • Civic action and policy choices", "readingTitle": "Classroom scenario", "reading": "A school-bus stop is unsafe. A planning memo states that the city owns the road, while the school district chooses bus-stop locations. Possible remedies include changing the stop or altering the road design.", "prompt": "What should the group do before demanding that the school district rebuild the road?", "choices": ["Direct both remedies to the district because school passengers are the people most affected", "Direct both remedies to the city because ownership of the road includes control of bus stops", "Determine which remedy each institution can authorize and coordinate the relevant requests", "Choose the most popular remedy and treat community support as sufficient authority to act"], "answer": 2, "source": "reference.html#authority", "where": "Read “CS 1 • Choose the responsible institution.” The affected population and the institution’s legal responsibility are different questions.", "hint": "The affected population and the institution’s legal responsibility are different questions.", "explanation": "The scenario divides authority. A stop-location request belongs with the district, while a road-design request involves the city. A practical plan identifies and coordinates those responsibilities.", "skill": "authority"}, {"id": "q6", "cs": "CS 1", "contentStatement": 1, "topic": "CS 1 • Civic action and policy choices", "readingTitle": "Classroom scenario", "reading": "Students propose later library hours. They survey people already inside the library at noon; most respondents favor later hours. The proposal says this proves the preferences of all county residents.", "prompt": "Which additional evidence would most strengthen the proposal’s claim about community need?", "choices": ["Repeat the noon survey among the same users and treat a larger total as countywide coverage", "Add more quotations from current noon visitors and retain the claim about all county residents", "Collect input from residents unable to visit at noon and compare demand with staffing costs", "Count favorable social-media reactions without checking whether users live in the county"], "answer": 2, "source": "reference.html#research", "where": "Read “CS 1 • Research before choosing.” Ask who the existing evidence leaves out and what information implementation would require.", "hint": "Ask who the existing evidence leaves out and what information implementation would require.", "explanation": "A noon-user sample can miss people whose schedules prevent attendance. Broader local input and staffing information better connect community need with a feasible proposal.", "skill": "research"}, {"id": "q7", "cs": "CS 1", "contentStatement": 1, "topic": "CS 1 • Civic action and policy choices", "readingTitle": "Classroom scenario", "reading": "A council candidate wins after promising a new recreation program. The council has not approved the program, and its funding must still go through the city’s budget procedure.", "prompt": "Which next step best recognizes the difference between electoral success and policy adoption?", "choices": ["Begin spending program funds because the election already authorized the proposed budget", "Treat campaign supporters’ donations as a substitute for council approval of public spending", "Ask election officials to certify the recreation program when they certify the vote totals", "Develop a funding proposal, then seek approval through the council’s required budget process"], "answer": 3, "source": "reference.html#process", "where": "Read “CS 1 • Political and public policy processes.” Winning office creates an opportunity to pursue policy; identify the remaining institutional step.", "hint": "Winning office creates an opportunity to pursue policy; identify the remaining institutional step.", "explanation": "The election chooses an officeholder. The program still requires the specified budget approval, so political success does not by itself enact the promised policy.", "skill": "process"}, {"id": "q8", "cs": "CS 1", "contentStatement": 1, "topic": "CS 1 • Civic action and policy choices", "readingTitle": "Classroom scenario", "reading": "Residents have researched litter, compared bin locations and obtained city approval for a pilot. City maintenance staff agree to supervise installation and track servicing costs.", "prompt": "Which step demonstrates implementation rather than preparation alone?", "choices": ["Prepare another presentation comparing possible bin locations without installing the pilot", "Hold a discussion of whether litter matters while postponing the approved installation work", "Carry out the approved installations with city staff and collect the planned follow-up data", "Publish a statement supporting the pilot without assigning anyone to carry out its tasks"], "answer": 2, "source": "reference.html#evaluate", "where": "Read “CS 1 • Evaluate after implementation.” Locate the step that actually carries out the approved plan and checks its operation.", "hint": "Locate the step that actually carries out the approved plan and checks its operation.", "explanation": "Implementation puts the approved plan into action. Installation and follow-up carry out the pilot; further presentations or endorsements alone remain preparatory activities.", "skill": "evaluate"}, {"id": "q9", "cs": "CS 1", "contentStatement": 1, "topic": "CS 1 • Civic action and policy choices", "readingTitle": "Classroom scenario", "reading": "A crossing project aimed to reduce collisions per 1,000 crossings. Six months later, total collisions are lower, but the number of people crossing has also fallen. The group has not calculated a rate.", "prompt": "Which evidence would best evaluate whether the project met its safety goal?", "choices": ["Use the lower collision total alone because a smaller count establishes a lower collision rate", "Count messages thanking the city and use that total as a substitute for collision evidence", "Compare the construction price with the original budget and treat that as the safety result", "Compare collisions per 1,000 crossings over comparable periods before and after the project"], "answer": 3, "source": "reference.html#compare-measures", "where": "Read “CS 1 / CS 3 • Compare like measures.” Match the evaluation measure to the stated goal and account for changing exposure.", "hint": "Match the evaluation measure to the stated goal and account for changing exposure.", "explanation": "The goal concerns risk per crossing. Comparable rates account for a change in the number of crossings; counts, gratitude and budget compliance answer different questions.", "skill": "compare-measures"}, {"id": "q10", "cs": "CS 1", "contentStatement": 1, "topic": "CS 1 • Civic action and policy choices", "readingTitle": "Classroom scenario", "reading": "Closing a street would create space for a weekend market. The fire department reports that the closure could lengthen emergency access to nearby buildings.", "prompt": "Which response best weighs an unintended consequence without abandoning the proposal’s goal?", "choices": ["Set emergency access aside because the closure’s stated purpose is economic rather than safety", "Reject the market without examining whether a different layout could address the access concern", "Compare the benefits and costs of market layouts that preserve emergency access to nearby buildings", "Use expected attendance as proof that emergency vehicles will have adequate access during closure"], "answer": 2, "source": "reference.html#costs", "where": "Read “CS 1 • Weigh consequences, costs and benefits.” An unintended effect calls for examining trade-offs and alternatives, not ignoring evidence.", "hint": "An unintended effect calls for examining trade-offs and alternatives, not ignoring evidence.", "explanation": "The access concern is relevant to the closure’s consequences. Comparing alternatives preserves consideration of the market while addressing a potentially serious cost.", "skill": "costs"}, {"id": "q11", "cs": "CS 2", "contentStatement": 2, "topic": "CS 2 • Organizations, media and strategy", "readingTitle": "Classroom scenario", "reading": "Organization A nominates candidates under its own label to win council seats. Organization B supports the same housing policy, endorses candidates and lobbies whichever officials are elected.", "prompt": "Which evidence most clearly identifies the first organization as a political party?", "choices": ["A communicates about housing, while B’s candidate endorsements make it an election agency", "A seeks to place its candidates in office; B’s described activity centers on policy influence", "A shares public-policy preferences, while B’s lobbying makes it a government department", "A uses an organizational label, while B’s support for candidates means it has no policy goals"], "answer": 1, "source": "reference.html#organizations", "where": "Read “CS 2 • Parties and interest groups.” Shared policy views and candidate support can occur in both; compare their central goals.", "hint": "Shared policy views and candidate support can occur in both; compare their central goals.", "explanation": "A’s stated purpose is winning office under its label. B’s activities support policy influence. Endorsing candidates does not by itself make B a political party or a government body.", "skill": "organizations"}, {"id": "q12", "cs": "CS 2", "contentStatement": 2, "topic": "CS 2 • Organizations, media and strategy", "readingTitle": "Classroom scenario", "reading": "A clean-water association supplies research to lawmakers, encourages members to testify and endorses candidates who share its priorities. It aims to influence water policy rather than govern as a party.", "prompt": "Which description best captures the association’s role?", "choices": ["It becomes a political party whenever it endorses a candidate for a government position", "It is an interest group combining several methods to influence the making and execution of policy", "It acts as an environmental agency because it supplies technical research to lawmakers", "It functions as an election board because it encourages members to participate publicly"], "answer": 1, "source": "reference.html#organizations", "where": "Read “CS 2 • Parties and interest groups.” Classify its purpose rather than treating any one tactic as proof of official authority.", "hint": "Classify its purpose rather than treating any one tactic as proof of official authority.", "explanation": "The association organizes a shared policy concern. Research, testimony and endorsements can all be interest-group methods; none turns it into an official agency or election board.", "skill": "organizations"}, {"id": "q13", "cs": "CS 2", "contentStatement": 2, "topic": "CS 2 • Organizations, media and strategy", "readingTitle": "Classroom scenario", "reading": "A neighborhood hearing is in four days. Many affected residents lack reliable internet. A local radio station offers an announcement, and stores allow printed notices at no charge. The group has little money.", "prompt": "Which outreach strategy best fits the stated audience, timing and resources?", "choices": ["Purchase a national digital advertisement using most of the budget to maximize distant views", "Publish a lengthy online-only report and assume affected residents will find it before the hearing", "Use local radio and printed notices with clear hearing times, locations and participation details", "Prepare a detailed newsletter for distribution next month after all current hearing dates have passed"], "answer": 2, "source": "reference.html#audience", "where": "Read “CS 2 • Match media to audience and purpose.” Consider access, location, deadline and the concrete action recipients need to take.", "hint": "Consider access, location, deadline and the concrete action recipients need to take.", "explanation": "Local radio and print reach residents through available channels before the hearing. The message also gives people the information needed to participate.", "skill": "audience"}, {"id": "q14", "cs": "CS 2", "contentStatement": 2, "topic": "CS 2 • Organizations, media and strategy", "readingTitle": "Classroom scenario", "reading": "A party and a transit-riders association both support expanded service. The party seeks council seats; the association’s immediate goal is to influence next month’s route hearing.", "prompt": "Which paired strategy best reflects the organizations’ different roles?", "choices": ["The party certifies election results; the association issues new routes to transit employees", "The party recruits election candidates; the association submits its ridership evidence to the hearing", "The party enforces current fares; the association appoints council members to support changes", "The party approves bus permits; the association treats endorsements as adopted transit policy"], "answer": 1, "source": "reference.html#organizations", "where": "Read “CS 2 • Parties and interest groups.” Keep election competition, policy influence and official governmental powers distinct.", "hint": "Keep election competition, policy influence and official governmental powers distinct.", "explanation": "Candidate recruitment fits the party’s goal of winning office. Presenting evidence fits an interest group’s goal of influencing a policy hearing without exercising the agency’s powers.", "skill": "organizations"}, {"id": "q15", "cs": "CS 2", "contentStatement": 2, "topic": "CS 2 • Organizations, media and strategy", "readingTitle": "Classroom scenario", "reading": "A state committee is reviewing school funding next week. Students have a short research report and want committee members to examine specific findings before the hearing.", "prompt": "Which combination offers the strongest defense of a viable strategy?", "choices": ["A neighborhood recreation club distributes sports schedules to officials in a different state", "A candidate committee circulates a general election slogan without addressing school funding", "An education-focused group sends a concise brief and source links directly to committee offices", "A media company posts a headline after the hearing and omits the report’s research findings"], "answer": 2, "source": "reference.html#viability", "where": "Read “CS 2 • Defend a viable civic strategy.” Match the group’s purpose, the decision maker, the message and the decision’s timing.", "hint": "Match the group’s purpose, the decision maker, the message and the decision’s timing.", "explanation": "The education group’s concern matches the issue, and a timely brief reaches the relevant officials with usable evidence. The strategy can be defended without guaranteeing policy success.", "skill": "viability"}, {"id": "q16", "cs": "CS 2", "contentStatement": 2, "topic": "CS 2 • Organizations, media and strategy", "readingTitle": "Classroom scenario", "reading": "An interest group’s video highlights benefits of a zoning proposal but leaves out a published estimate of its costs. The quoted benefit figures themselves are accurate.", "prompt": "What is the best assessment of the video’s role in the policy discussion?", "choices": ["Its selective framing warrants checking omitted evidence even though quoted figures may be accurate", "Its accurate quotations establish that its overall presentation covers the relevant policy evidence", "Its advocacy purpose establishes that the quoted benefit figures must have been invented", "Its use of video removes the need to identify who produced the message or who it targets"], "answer": 0, "source": "reference.html#bias", "where": "Read “CS 3 • Investigate interests and assumptions.” Separate the accuracy of an individual fact from the completeness of a persuasive presentation.", "hint": "Separate the accuracy of an individual fact from the completeness of a persuasive presentation.", "explanation": "An advocacy message can quote real figures while omitting relevant context. Readers should assess the selection and compare credible evidence rather than automatically accept or reject the entire message.", "skill": "bias"}, {"id": "q17", "cs": "CS 2", "contentStatement": 2, "topic": "CS 2 • Organizations, media and strategy", "readingTitle": "Classroom scenario", "reading": "A party publishes a platform favoring expanded transit. Students want to know what the party says it will pursue if its candidates gain office.", "prompt": "Which use of the platform is justified?", "choices": ["Use it as proof that transit expansion has already been adopted through the city’s procedures", "Use it to establish that every future officeholder will vote identically on each funding detail", "Use it as a substitute for checking the legal authority and budget needed for implementation", "Use it to identify the party’s priorities, then examine later decisions to assess follow-through"], "answer": 3, "source": "reference.html#viability", "where": "Read “CS 2 • Defend a viable civic strategy.” A statement of goals is evidence of intentions, not proof that the goals have been enacted.", "hint": "A statement of goals is evidence of intentions, not proof that the goals have been enacted.", "explanation": "A platform communicates priorities to voters. Whether those priorities become policy depends on later decisions, authority and procedures; the document itself is not an enacted program.", "skill": "viability"}, {"id": "q18", "cs": "CS 2", "contentStatement": 2, "topic": "CS 2 • Organizations, media and strategy", "readingTitle": "Classroom scenario", "reading": "A nonprofit sends residents the text of a pending federal bill and asks them to contact their senators with comments before a committee decision.", "prompt": "Which explanation most accurately links the association’s action to civic involvement?", "choices": ["It administers a law already in force because it distributes the bill’s text to local residents", "It takes over the senators’ legislative authority when enough residents send written comments", "It becomes an election board because it encourages residents to communicate with public officials", "It mobilizes residents’ policy input without claiming the official authority to enact the bill"], "answer": 3, "source": "reference.html#viability", "where": "Read “CS 2 • Defend a viable civic strategy.” Distinguish participation aimed at influencing a decision from making that decision officially.", "hint": "Distinguish participation aimed at influencing a decision from making that decision officially.", "explanation": "The association encourages participation in a policy process. Residents’ comments may influence officials, but the association is not enacting or administering the pending bill.", "skill": "viability"}, {"id": "q19", "cs": "CS 2", "contentStatement": 2, "topic": "CS 2 • Organizations, media and strategy", "readingTitle": "Classroom scenario", "reading": "A campaign wants commuters to attend a transportation forum. The radio spot is short, while the evidence supporting the campaign’s position requires tables and a longer explanation.", "prompt": "Which communication plan best fits both the audience and the information needs?", "choices": ["Use the spot for key details and direct listeners to an accessible written evidence summary", "Read the entire numerical appendix rapidly on air and omit the forum’s time and location", "Replace the supporting evidence with a slogan because a short broadcast cannot include tables", "Publish the full report without distributing forum details through channels commuters use"], "answer": 0, "source": "reference.html#audience", "where": "Read “CS 2 • Match media to audience and purpose.” Different channels can perform complementary jobs within one communication strategy.", "hint": "Different channels can perform complementary jobs within one communication strategy.", "explanation": "The short spot can invite participation while directing listeners to evidence in a suitable format. Matching media to purpose does not require abandoning the supporting research.", "skill": "audience"}, {"id": "q20", "cs": "CS 2", "contentStatement": 2, "topic": "CS 2 • Organizations, media and strategy", "readingTitle": "Classroom scenario", "reading": "After local notices were distributed, hearing attendance rose from 20 to 45. Weather was also better, and another group promoted the event. Several attendees say they learned about it from the notices.", "prompt": "Which conclusion is best supported by the outreach results?", "choices": ["The notices caused the entire increase because attendance rose after they were distributed", "The notices failed because weather and another group’s publicity also could have influenced turnout", "The notices persuaded every attendee to support the proposal because participation increased", "The notices reached some attendees, but the increase cannot be attributed to them alone"], "answer": 3, "source": "reference.html#outreach-evaluation", "where": "Read “CS 2 • Evaluate outreach without overclaiming.” Distinguish evidence of reaching people from proof of sole causation or agreement.", "hint": "Distinguish evidence of reaching people from proof of sole causation or agreement.", "explanation": "Attendees’ reports support some reach. The before-and-after increase has other plausible influences and does not establish that all participants agreed with the group.", "skill": "outreach-evaluation"}, {"id": "q21", "cs": "CS 3", "contentStatement": 3, "topic": "CS 3 • Evaluating evidence and credibility", "readingTitle": "Classroom scenario", "reading": "A city agency tests water at a treatment plant in March. A university tests household taps in July. Their results differ, and both reports describe their methods.", "prompt": "What should students check before concluding that one water-quality report disproves the other?", "choices": ["Which institution has more employees, treating organizational size as the decisive credibility test", "Whether location, timing and measurement differences account for the reported results", "Which report supports their preferred policy, treating agreement as evidence of sampling quality", "Whether both reports use the same page design, treating similar presentation as corroboration"], "answer": 1, "source": "reference.html#corroborate", "where": "Read “CS 3 • Compare credible sources.” Compare what was measured and under which conditions before treating findings as contradictory.", "hint": "Compare what was measured and under which conditions before treating findings as contradictory.", "explanation": "The reports concern different locations and dates. Method and context can explain variation; disagreement does not identify which report, if either, is unreliable.", "skill": "corroborate"}, {"id": "q22", "cs": "CS 3", "contentStatement": 3, "topic": "CS 3 • Evaluating evidence and credibility", "readingTitle": "Classroom scenario", "reading": "A funding article says costs fell by 30%. It names no original report, baseline year, total dollar figures or calculation method.", "prompt": "What should a reader do before relying on the percentage as verified evidence?", "choices": ["Treat the figure as verified because percentages make a claim more precise than general wording", "Trace the figure to original data and establish the period and basis of comparison", "Treat the figure as current because the article discussing it was published this morning", "Infer the missing baseline from the article’s title instead of checking the original records"], "answer": 1, "source": "reference.html#evidence", "where": "Read “CS 3 • Trace evidence to the conclusion.” Precision in wording does not provide the missing evidence or comparison period.", "hint": "Precision in wording does not provide the missing evidence or comparison period.", "explanation": "The reader needs the origin, baseline and calculation to verify what the percentage represents. A recent article can repeat an old or unsupported statistic.", "skill": "evidence"}, {"id": "q23", "cs": "CS 3", "contentStatement": 3, "topic": "CS 3 • Evaluating evidence and credibility", "readingTitle": "Classroom scenario", "reading": "A well-known laboratory scientist writes a report predicting how a city tax change will affect employment. The report gives limited information about the economic method used.", "prompt": "Which evaluation best avoids assuming that expertise transfers automatically between subjects?", "choices": ["Examine relevant economic expertise and the evidence and assumptions behind the prediction", "Accept the prediction because scientific recognition establishes expertise on every technical issue", "Reject the prediction because a scientist’s work outside a specialty cannot contain useful evidence", "Use audience size to resolve the question instead of examining the report’s economic reasoning"], "answer": 0, "source": "reference.html#expertise", "where": "Read “CS 3 • Check relevant expertise.” Relevant qualifications matter, but they should be considered alongside the actual argument.", "hint": "Relevant qualifications matter, but they should be considered alongside the actual argument.", "explanation": "Expertise is subject-specific. Readers can examine relevant qualifications, methods and evidence without automatically accepting the scientist’s conclusion or dismissing it because of the writer’s background.", "skill": "expertise"}, {"id": "q24", "cs": "CS 3", "contentStatement": 3, "topic": "CS 3 • Evaluating evidence and credibility", "readingTitle": "Classroom scenario", "reading": "A development agency releases a favorable project report just before a funding vote. The report was prepared by a contractor that would benefit if the project proceeds.", "prompt": "How should the report’s circumstances affect evaluation?", "choices": ["Examine incentives, methods and omitted evidence without assuming the findings are false", "Accept the findings because release near the vote establishes reliable research methods", "Reject each number because a financial interest proves that every measurement was fabricated", "Ignore the timing and funding relationship because published reports are independent by definition"], "answer": 0, "source": "reference.html#context", "where": "Read “CS 3 • Examine date, purpose and circumstances.” Context can reveal incentives; it does not replace examination of evidence.", "hint": "Context can reveal incentives; it does not replace examination of evidence.", "explanation": "The timing and contractor’s interest are relevant circumstances. They justify close evaluation and corroboration, but do not establish whether particular findings are true or false.", "skill": "context"}, {"id": "q25", "cs": "CS 3", "contentStatement": 3, "topic": "CS 3 • Evaluating evidence and credibility", "readingTitle": "Classroom scenario", "reading": "Six websites repeat one press release supporting a project. Two separate research teams publish their own documented measurements that disagree with the release.", "prompt": "Which claim about corroboration is strongest?", "choices": ["The six copies are one information chain; compare the independent teams’ methods and findings", "The six websites provide six independent confirmations, so they outweigh the two research teams", "The two teams must be correct because a smaller number of sources is inherently more credible", "Disagreement prevents evaluating any source until all publishers report exactly the same result"], "answer": 0, "source": "reference.html#corroborate", "where": "Read “CS 3 • Compare credible sources.” Count independent origins of evidence, then examine quality rather than taking a simple vote.", "hint": "Count independent origins of evidence, then examine quality rather than taking a simple vote.", "explanation": "Repeated copies do not create independent corroboration. The separate research deserves examination, but its methods and relevance still need evaluation.", "skill": "corroborate"}, {"id": "q26", "cs": "CS 3", "contentStatement": 3, "topic": "CS 3 • Evaluating evidence and credibility", "readingTitle": "Classroom scenario", "reading": "A transit report lists annual spending of $100,000 for 10,000 rides before a change, and $120,000 for 15,000 rides after it. It claims that spending per ride fell.", "prompt": "Which conclusion correctly interprets the figures?", "choices": ["The report contradicts itself because any increase in total spending means unit costs rose", "Spending per ride rose from $8 to $10 because the program handled a larger number of rides", "Spending per ride fell from $10 to $8 while total annual spending increased", "Total spending fell by 20% because the cost per ride declined over the two periods"], "answer": 2, "source": "reference.html#compare-measures", "where": "Read “CS 1 / CS 3 • Compare like measures.” Calculate the same measure in both periods; total spending and spending per ride are different.", "hint": "Calculate the same measure in both periods; total spending and spending per ride are different.", "explanation": "The calculations are $100,000 ÷ 10,000 = $10 and $120,000 ÷ 15,000 = $8. Lower unit cost and higher total spending can both be true, so those statements do not conflict.", "skill": "compare-measures"}, {"id": "q27", "cs": "CS 3", "contentStatement": 3, "topic": "CS 3 • Evaluating evidence and credibility", "readingTitle": "Classroom scenario", "reading": "An article argues that moving all permit applications online will make the process easier for every resident. It provides evidence that the website processes forms quickly.", "prompt": "Which question most directly tests the argument’s unstated assumption?", "choices": ["Does the website use a color scheme that matches other pages operated by the same office?", "Has the office announced a name for the new website in its latest public newsletter?", "Do most office employees prefer the website’s logo to the design used on the old forms?", "Can residents with differing internet access and accessibility needs use the online process?"], "answer": 3, "source": "reference.html#bias", "where": "Read “CS 3 • Investigate interests and assumptions.” Look for a condition needed to move from fast processing to a claim about every resident.", "hint": "Look for a condition needed to move from fast processing to a claim about every resident.", "explanation": "The argument assumes residents can access and use the online system. Processing speed alone does not establish access or usability for all affected people.", "skill": "bias"}, {"id": "q28", "cs": "CS 3", "contentStatement": 3, "topic": "CS 3 • Evaluating evidence and credibility", "readingTitle": "Classroom scenario", "reading": "A newspaper quotes several opponents of a proposal and no supporters. The quotations may be accurate, but students need to evaluate the proposal’s likely effects.", "prompt": "Which next step best evaluates the article without assuming that balance alone guarantees accuracy?", "choices": ["Seek relevant records and credible competing analyses, then compare the evidence behind claims", "Add an equal number of favorable quotations and regard that numerical balance as verification", "Accept the opponents’ forecast because several people repeated the same criticism in the article", "Discard the quoted information without checking it because a selective article cannot contain facts"], "answer": 0, "source": "reference.html#bias", "where": "Read “CS 3 • Investigate interests and assumptions.” Additional perspectives help, but the strength and relevance of their evidence still matter.", "hint": "Additional perspectives help, but the strength and relevance of their evidence still matter.", "explanation": "Students should widen the evidence base and evaluate claims, not simply count opposing quotations. A selective article can contain accurate facts while leaving important information out.", "skill": "bias"}, {"id": "q29", "cs": "CS 3", "contentStatement": 3, "topic": "CS 3 • Evaluating evidence and credibility", "readingTitle": "Classroom scenario", "reading": "A graph shows participation rising from 100 to 102 people. Its vertical axis runs from 99 to 103, so the plotted increase occupies half the graph’s vertical range.", "prompt": "Which interpretation best distinguishes the displayed impression from the numerical change?", "choices": ["Participation rose 50% because the plotted increase uses half the graph’s vertical range", "Participation rose 2%; the narrow axis magnifies its appearance and needs contextual evaluation", "The figures must be fabricated because a graph cannot validly show a vertical axis above zero", "The graph proves the policy caused the increase because the later point is above the earlier one"], "answer": 1, "source": "reference.html#visual-data", "where": "Read “CS 3 • Read graph values and scales.” Use the values to calculate the change, then evaluate what the scale emphasizes.", "hint": "Use the values to calculate the change, then evaluate what the scale emphasizes.", "explanation": "The increase is 2 ÷ 100 = 2%. The narrow scale emphasizes that small change; it does not by itself prove fabricated values, invalidate every such graph or establish causation.", "skill": "visual-data"}, {"id": "q30", "cs": "CS 3", "contentStatement": 3, "topic": "CS 3 • Evaluating evidence and credibility", "readingTitle": "Classroom scenario", "reading": "An agency and a university independently sample the same population during the same period. They explain their methods and report similar findings with acknowledged uncertainty.", "prompt": "Which statement gives the best reason for increased confidence while recognizing remaining limits?", "choices": ["Agreement establishes certainty, so the reported sampling uncertainty can be disregarded", "Institutional names establish accuracy without examining how either sample was collected", "Independent, comparable evidence agrees, although methods and limitations still need review", "Similar findings establish that both studies used the same original sample and copied one another"], "answer": 2, "source": "reference.html#corroborate", "where": "Read “CS 3 • Compare credible sources.” Look for independence, comparable measurements and transparent methods rather than certainty.", "hint": "Look for independence, comparable measurements and transparent methods rather than certainty.", "explanation": "Comparable results from independent work can strengthen confidence. Agreement does not remove measurement limits or the need to examine how the studies were conducted.", "skill": "corroborate"}, {"id": "q31", "cs": "CS 4", "contentStatement": 4, "topic": "CS 4 • Democratic agreement", "readingTitle": "Classroom scenario", "reading": "A council member presents maintenance estimates to persuade undecided colleagues to support a park plan. No offers or concessions have yet been exchanged.", "prompt": "Which explanation identifies the member’s most direct use of an interpersonal skill?", "choices": ["The member completes a compromise by giving up part of the plan during mutual concessions", "The member uses persuasion by offering evidence intended to change colleagues’ judgments", "The member establishes consensus because presenting evidence means all members accept the plan", "The member implements the project because a supporting argument authorizes construction spending"], "answer": 1, "source": "reference.html#persuasion", "where": "Read “CS 4 • Persuasion.” Distinguish trying to convince others from a settled agreement or official implementation.", "hint": "Distinguish trying to convince others from a settled agreement or official implementation.", "explanation": "The evidence is offered to influence judgment, which is persuasion. The case does not yet show exchanged terms, concessions, shared acceptance or authorization to implement the project.", "skill": "persuasion"}, {"id": "q32", "cs": "CS 4", "contentStatement": 4, "topic": "CS 4 • Democratic agreement", "readingTitle": "Classroom scenario", "reading": "Two neighborhood groups exchange offers about a festival’s closing time and cleanup duties. They have not agreed on final terms or obtained the required event approval.", "prompt": "Why is this negotiation rather than implementation?", "choices": ["They are working out terms; implementation would carry out an approved arrangement", "They are enforcing terms; implementation would begin when someone first proposes a closing time", "They are counting votes; implementation would require every resident to become a group member", "They are certifying an election; implementation would consist of reporting the winning vote total"], "answer": 0, "source": "reference.html#negotiate", "where": "Read “CS 4 • Negotiation.” Ask whether participants are still settling the arrangement or carrying it out.", "hint": "Ask whether participants are still settling the arrangement or carrying it out.", "explanation": "Offers about unresolved terms are negotiation. The parties still need agreement and the specified approval before implementing the event arrangement.", "skill": "negotiate"}, {"id": "q33", "cs": "CS 4", "contentStatement": 4, "topic": "CS 4 • Democratic agreement", "readingTitle": "Classroom scenario", "reading": "One group originally requests a festival until 11 p.m.; another requests 8 p.m. They agree on 9:30 p.m., with a revised cleanup schedule each side can accept.", "prompt": "What makes the outcome a compromise?", "choices": ["Both receive their full initial demands because a shared agreement removes every trade-off", "The later proposal becomes law as soon as one group presents reasons for supporting it", "The agreement proves the two groups had identical preferences before the discussion began", "Both accept concessions from their original positions to obtain a workable settlement"], "answer": 3, "source": "reference.html#compromise", "where": "Read “CS 4 • Compromise.” Compare the settlement with each group’s starting demand.", "hint": "Compare the settlement with each group’s starting demand.", "explanation": "Each side accepts a change from its requested time, along with agreed cleanup terms. That reciprocal adjustment is compromise, even though neither side gets its original preference in full.", "skill": "compromise"}, {"id": "q34", "cs": "CS 4", "contentStatement": 4, "topic": "CS 4 • Democratic agreement", "readingTitle": "Classroom scenario", "reading": "Committee members prefer three different designs. After discussion and revisions, every member says the same final design is acceptable, though some still prefer another design.", "prompt": "Which conclusion best distinguishes consensus from identical preferences?", "choices": ["They have built consensus on an acceptable decision without eliminating preference differences", "They have failed to reach agreement because consensus requires the same first-choice design", "They have held a majority vote because acceptance means the largest faction won a ballot", "They have avoided deliberation because revised designs cannot reflect earlier disagreement"], "answer": 0, "source": "reference.html#consensus", "where": "Read “CS 4 • Consensus building.” A person can accept a shared outcome while retaining a different personal first choice.", "hint": "A person can accept a shared outcome while retaining a different personal first choice.", "explanation": "Consensus building seeks broad acceptance of a decision, not identical private preferences. The discussion and revisions have produced an acceptable shared outcome despite remaining differences.", "skill": "consensus"}, {"id": "q35", "cs": "CS 4", "contentStatement": 4, "topic": "CS 4 • Democratic agreement", "readingTitle": "Classroom scenario", "reading": "Two groups repeat fixed demands about a meeting location. One needs wheelchair access; the other needs a site near a bus route. Neither has discussed those underlying needs.", "prompt": "Which intervention is most likely to move these talks forward?", "choices": ["Repeat the initial demands more forcefully so one side will stop describing its concerns", "Identify both needs and compare locations that might satisfy access and transport concerns", "Choose the first group’s site because making the earliest demand establishes priority", "End all discussion until the groups independently develop the same location preference"], "answer": 1, "source": "reference.html#negotiate", "where": "Read “CS 4 • Negotiation.” Distinguish stated positions from the interests a workable option must address.", "hint": "Distinguish stated positions from the interests a workable option must address.", "explanation": "Exploring underlying needs creates opportunities for new proposals. Merely repeating positions or requiring identical preferences does not help identify a location both groups could accept.", "skill": "negotiate"}, {"id": "q36", "cs": "CS 4", "contentStatement": 4, "topic": "CS 4 • Democratic agreement", "readingTitle": "Classroom scenario", "reading": "Board members cite evidence, exchange proposals and accept revisions to gain broad support. They then hold the formal vote required to adopt the school policy.", "prompt": "Which account best explains how the skills and formal procedures work together?", "choices": ["The exchange of proposals already enacts the policy, making the required formal vote redundant", "The formal vote shows that persuasion and negotiation played no role in developing the policy", "Accepting revisions transfers the board’s legal authority to whichever speaker proposed them first", "Interpersonal skills help build agreement, while the formal vote performs the required adoption"], "answer": 3, "source": "reference.html#combine", "where": "Read “CS 4 • Skills working together.” Separate the work of reaching support from the official act that gives the decision effect.", "hint": "Separate the work of reaching support from the official act that gives the decision effect.", "explanation": "Persuasion, negotiation and compromise can help members develop agreement. Those skills complement rather than replace the stipulated adoption procedure.", "skill": "combine"}, {"id": "q37", "cs": "CS 4", "contentStatement": 4, "topic": "CS 4 • Democratic agreement", "readingTitle": "Classroom scenario", "reading": "A legislator uses cost estimates to argue for a facility plan. Opponents want a smaller project, but neither side has changed its starting position.", "prompt": "Which action would add compromise to the persuasion already taking place?", "choices": ["The legislator repeats the existing cost estimates while opponents repeat their original objections", "The legislator publishes another explanation without changing the plan’s requested funding", "Opponents listen to the budget argument but continue to insist on their full initial demands", "Both sides accept a reduced project and adjusted funding in exchange for a shared agreement"], "answer": 3, "source": "reference.html#combine", "where": "Read “CS 4 • Skills working together.” Persuasion tries to convince; compromise requires participants to yield something.", "hint": "Persuasion tries to convince; compromise requires participants to yield something.", "explanation": "Reciprocal adjustments to the project and funding introduce concessions. Repeating or listening to arguments may be persuasion or discussion, but does not by itself establish compromise.", "skill": "combine"}, {"id": "q38", "cs": "CS 4", "contentStatement": 4, "topic": "CS 4 • Democratic agreement", "readingTitle": "Classroom scenario", "reading": "Residents disagree about cameras in a public park, but all want users to feel safe. They have not compared other safety measures or discussed privacy concerns.", "prompt": "How can identifying the shared goal help the discussion?", "choices": ["It provides common ground for exploring options that address safety and remaining concerns", "It establishes agreement on cameras because everyone accepts the broad goal of park safety", "It removes the need to compare evidence because a shared goal establishes which method works", "It proves concerns about privacy are outside the discussion because safety has been identified"], "answer": 0, "source": "reference.html#combine", "where": "Read “CS 4 • Skills working together.” Agreement on an objective does not establish agreement on a particular means.", "hint": "Agreement on an objective does not establish agreement on a particular means.", "explanation": "A shared safety goal can support discussion of options and trade-offs. It does not settle whether cameras are effective or how privacy should be addressed.", "skill": "combine"}, {"id": "q39", "cs": "CS 4", "contentStatement": 4, "topic": "CS 4 • Democratic agreement", "readingTitle": "Classroom scenario", "reading": "A council adopts a policy by a lawful 4–3 vote. The three opposing members remain concerned about implementation costs. The council can review implementation details next month.", "prompt": "Which next step could improve cooperation without confusing consensus with the formal vote?", "choices": ["Treat the policy as never adopted because a democratic decision requires unanimous personal agreement", "Exclude the opposing members from implementation discussion because the majority has already won", "Hear the cost concerns and negotiate workable details while recognizing that adoption already occurred", "Reclassify the original vote as consensus because the formal procedure produced an official decision"], "answer": 2, "source": "reference.html#consensus", "where": "Read “CS 4 • Consensus building.” A valid majority decision and continued efforts to address disagreement can coexist.", "hint": "A valid majority decision and continued efforts to address disagreement can coexist.", "explanation": "The vote can adopt the policy without establishing consensus. Discussing practical concerns afterward may improve implementation and cooperation without pretending that the original disagreement vanished.", "skill": "consensus"}, {"id": "q40", "cs": "CS 4", "contentStatement": 4, "topic": "CS 4 • Democratic agreement", "readingTitle": "Classroom scenario", "reading": "An authorized committee must allocate emergency repairs by the end of the day. Members have safety reports and can hear brief statements from affected groups before their required decision.", "prompt": "Which approach best balances meaningful participation with the stated need to decide?", "choices": ["Review the evidence, hear key concerns, negotiate feasible changes and explain the timely decision", "Delay every repair allocation until all residents personally prefer the same project sequence", "Let the longest-serving speaker choose the allocation without reviewing the available safety reports", "Announce a decision before hearing concerns and describe the absence of discussion as consensus"], "answer": 0, "source": "reference.html#combine", "where": "Read “CS 4 • Skills working together.” Participation can inform a timely decision without requiring identical preferences from every resident.", "hint": "Participation can inform a timely decision without requiring identical preferences from every resident.", "explanation": "The proposed approach uses evidence and interpersonal skills within the decision deadline. It permits action while making room for relevant concerns and an explanation of the choice.", "skill": "combine"}];
